import { ButtonHTMLAttributes, ReactNode } from 'react'

export const BOX_VARIANT = {
  DEFAULT: 'default',
} as const
export type BoxVariant = keyof typeof BOX_VARIANT

export const boxVariant: Record<BoxVariant, string> = {
  DEFAULT: 'bg-black hover:bg-black-800 active:bg-grey-900',
}

export interface BoxProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  children?: ReactNode
  variant?: BoxVariant
  isDisabled?: boolean
}

export const Box = ({ variant = 'DEFAULT', isDisabled = false, children }: BoxProps) => {
  return (
    <div
      className={`overflow-hidden rounded-lg bg-white shadow-[0px_0px_8px_0px_rgba(0,0,0,0.05)]  
                flex`}
    >
      {children ? children : 'test'}
    </div>
  )
}
